$chapters = @"

,  {"id":"SAT-10-05-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Simplify: (x^2 - 4)/(x - 2)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x + 2"},{"id":"b","text":"x - 2"},{"id":"c","text":"x^2"},{"id":"d","text":"x + 4"}],"correctOptionId":"a","explanation":"x^2 - 4 = (x+2)(x-2), so result = x + 2.","difficulty":"Easy"},
  {"id":"SAT-10-05-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"What is i^2 where i is the imaginary unit?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"1"},{"id":"b","text":"-1"},{"id":"c","text":"i"},{"id":"d","text":"-i"}],"correctOptionId":"b","explanation":"By definition, i^2 = -1.","difficulty":"Easy"},
  {"id":"SAT-10-05-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"If log10(100) = x, what is x?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"1"},{"id":"b","text":"2"},{"id":"c","text":"10"},{"id":"d","text":"100"}],"correctOptionId":"b","explanation":"10^2 = 100, so log10(100) = 2.","difficulty":"Easy"},
  {"id":"SAT-10-05-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Remainder when x^3 + 2x - 1 divided by x - 1?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"2"},{"id":"b","text":"0"},{"id":"c","text":"1"},{"id":"d","text":"-1"}],"correctOptionId":"a","explanation":"f(1) = 1 + 2 - 1 = 2.","difficulty":"Easy"},
  {"id":"SAT-10-05-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Solve: 2^x = 16","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"4"},{"id":"d","text":"8"}],"correctOptionId":"c","explanation":"2^4 = 16, so x = 4.","difficulty":"Easy"},
  {"id":"SAT-10-05-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Sum of geometric series: 1 + 2 + 4 + 8 + 16?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"31"},{"id":"b","text":"32"},{"id":"c","text":"15"},{"id":"d","text":"24"}],"correctOptionId":"a","explanation":"Sum = (2^5 - 1)/(2 - 1) = 31.","difficulty":"Easy"},
  {"id":"SAT-10-05-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Factor completely: x^3 - 8","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"(x - 2)(x^2 + 2x + 4)"},{"id":"b","text":"(x - 2)^3"},{"id":"c","text":"(x + 2)(x^2 - 2x + 4)"},{"id":"d","text":"(x - 2)(x^2 - 4)"}],"correctOptionId":"a","explanation":"Difference of cubes: x^3 - 8 = (x-2)(x^2+2x+4).","difficulty":"Easy"},
  {"id":"SAT-10-05-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"What is C(6,2)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"15"},{"id":"b","text":"30"},{"id":"c","text":"12"},{"id":"d","text":"36"}],"correctOptionId":"a","explanation":"C(6,2) = 6!/(2!4!) = (6x5)/(2x1) = 15.","difficulty":"Easy"},
  {"id":"SAT-10-05-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"If f(x) = 3^(x-1), what is f(2)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"3"},{"id":"b","text":"9"},{"id":"c","text":"1"},{"id":"d","text":"27"}],"correctOptionId":"a","explanation":"f(2) = 3^(2-1) = 3^1 = 3.","difficulty":"Easy"},
  {"id":"SAT-10-05-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"First term of arithmetic sequence: 5, 8, 11, 14, ...?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"3"},{"id":"b","text":"5"},{"id":"c","text":"8"},{"id":"d","text":"2"}],"correctOptionId":"b","explanation":"The first term is 5.","difficulty":"Easy"},
  {"id":"SAT-10-05-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Simplify: (2 + 3i) + (4 - 5i)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"6 - 2i"},{"id":"b","text":"6 + 2i"},{"id":"c","text":"2 + 8i"},{"id":"d","text":"-2 + 2i"}],"correctOptionId":"a","explanation":"(2+4) + (3-5)i = 6 - 2i.","difficulty":"Medium"},
  {"id":"SAT-10-05-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"10th term of arithmetic sequence 3, 7, 11, 15, ...?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"39"},{"id":"b","text":"43"},{"id":"c","text":"35"},{"id":"d","text":"37"}],"correctOptionId":"a","explanation":"a10 = 3 + (10-1)(4) = 3 + 36 = 39.","difficulty":"Medium"},
  {"id":"SAT-10-05-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Solve: log2(x) + log2(x-2) = 3","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x = 4"},{"id":"b","text":"x = 8"},{"id":"c","text":"x = -2"},{"id":"d","text":"x = 2"}],"correctOptionId":"a","explanation":"log2(x(x-2)) = 3 -> x(x-2) = 8 -> x^2-2x-8 = 0 -> (x-4)(x+2) = 0. x = 4.","difficulty":"Medium"},
  {"id":"SAT-10-05-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"How many ways can 5 books be arranged on a shelf?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"120"},{"id":"b","text":"25"},{"id":"c","text":"60"},{"id":"d","text":"24"}],"correctOptionId":"a","explanation":"5! = 120.","difficulty":"Medium"},
  {"id":"SAT-10-05-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Common ratio of 6, 18, 54, 162, ...?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"3"},{"id":"b","text":"12"},{"id":"c","text":"9"},{"id":"d","text":"6"}],"correctOptionId":"a","explanation":"18/6 = 3, 54/18 = 3. Common ratio = 3.","difficulty":"Medium"},
  {"id":"SAT-10-05-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Simplify: (3 + i)(2 - 4i)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"10 - 10i"},{"id":"b","text":"6 - 10i"},{"id":"c","text":"-10 + 2i"},{"id":"d","text":"6 + 10i"}],"correctOptionId":"a","explanation":"6 - 12i + 2i - 4i^2 = 6 - 10i + 4 = 10 - 10i.","difficulty":"Medium"},
  {"id":"SAT-10-05-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"If log3(x) = 4, what is x?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"12"},{"id":"b","text":"81"},{"id":"c","text":"27"},{"id":"d","text":"64"}],"correctOptionId":"b","explanation":"x = 3^4 = 81.","difficulty":"Medium"},
  {"id":"SAT-10-05-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Sum of first 8 terms of 2, 6, 18, 54, ...?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"6560"},{"id":"b","text":"2186"},{"id":"c","text":"3280"},{"id":"d","text":"1094"}],"correctOptionId":"a","explanation":"S8 = 2(3^8-1)/(3-1) = 2(6561-1)/2 = 6560.","difficulty":"Medium"},
  {"id":"SAT-10-05-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"3-person committees from 8 people?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"56"},{"id":"b","text":"336"},{"id":"c","text":"24"},{"id":"d","text":"72"}],"correctOptionId":"a","explanation":"C(8,3) = 8!/(3!5!) = (8x7x6)/(3x2x1) = 56.","difficulty":"Medium"},
  {"id":"SAT-10-05-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Modulus of complex number 3 - 4i?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5"},{"id":"b","text":"7"},{"id":"c","text":"1"},{"id":"d","text":"25"}],"correctOptionId":"a","explanation":"|3-4i| = sqrt(3^2+(-4)^2) = sqrt(9+16) = sqrt(25) = 5.","difficulty":"Medium"},
  {"id":"SAT-10-05-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Solve: 2^(2x) - 5*2^x + 4 = 0","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x = 0 or x = 2"},{"id":"b","text":"x = 1 only"},{"id":"c","text":"x = 0 or x = 1"},{"id":"d","text":"x = 2 only"}],"correctOptionId":"a","explanation":"Let u = 2^x: u^2 - 5u + 4 = 0 -> (u-1)(u-4) = 0 -> x = 0 or x = 2.","difficulty":"Hard"},
  {"id":"SAT-10-05-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"20th term of geometric sequence 5, 10, 20, 40, ...?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5 * 2^19"},{"id":"b","text":"5 * 2^20"},{"id":"c","text":"10 * 2^19"},{"id":"d","text":"5 * 2^18"}],"correctOptionId":"a","explanation":"a20 = 5 * 2^(20-1) = 5 * 2^19.","difficulty":"Hard"},
  {"id":"SAT-10-05-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"(1+i)^2 = a + bi. What are a and b?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"a=0, b=2"},{"id":"b","text":"a=2, b=2"},{"id":"c","text":"a=0, b=-2"},{"id":"d","text":"a=2, b=0"}],"correctOptionId":"a","explanation":"(1+i)^2 = 1 + 2i + i^2 = 1 + 2i - 1 = 2i. So a=0, b=2.","difficulty":"Hard"},
  {"id":"SAT-10-05-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"How many 4-letter arrangements from A,B,C,D,E with no repeats?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"120"},{"id":"b","text":"60"},{"id":"c","text":"24"},{"id":"d","text":"256"}],"correctOptionId":"a","explanation":"P(5,4) = 5!/(5-4)! = 5!/1! = 120.","difficulty":"Hard"},
  {"id":"SAT-10-05-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Solve: log(x) + log(x+3) = 1","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x = 2"},{"id":"b","text":"x = 5"},{"id":"c","text":"x = -5"},{"id":"d","text":"x = 2 or x = -5"}],"correctOptionId":"a","explanation":"log(x(x+3)) = 1 -> x(x+3) = 10 -> x^2+3x-10 = 0 -> (x+5)(x-2) = 0. x = 2 (x > 0).","difficulty":"Hard"},
  {"id":"SAT-10-05-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"If P(n,2) = 30, what is n?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"6"},{"id":"b","text":"5"},{"id":"c","text":"10"},{"id":"d","text":"15"}],"correctOptionId":"a","explanation":"n(n-1) = 30 -> n^2-n-30 = 0 -> (n-6)(n+5) = 0. n = 6.","difficulty":"Hard"},
  {"id":"SAT-10-05-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"What is the sum of infinite geometric series 1 + 1/2 + 1/4 + 1/8 + ...?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"2"},{"id":"b","text":"1"},{"id":"c","text":"infinity"},{"id":"d","text":"4"}],"correctOptionId":"a","explanation":"Sum = a/(1-r) = 1/(1-1/2) = 1/(1/2) = 2.","difficulty":"Hard"},
  {"id":"SAT-10-05-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"If z = 3 + 4i, what is z * z_bar?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"25"},{"id":"b","text":"7"},{"id":"c","text":"24"},{"id":"d","text":"1"}],"correctOptionId":"a","explanation":"z * z_bar = |z|^2 = 3^2 + 4^2 = 25.","difficulty":"Hard"},
  {"id":"SAT-10-05-29","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"How many 2-element subsets from {1,2,3,4,5,6} sum to 7?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"3"},{"id":"b","text":"6"},{"id":"c","text":"2"},{"id":"d","text":"4"}],"correctOptionId":"a","explanation":"Pairs summing to 7: (1,6), (2,5), (3,4). That's 3 subsets.","difficulty":"Hard"},
  {"id":"SAT-10-05-30","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 5: Advanced Mathematics","yearEC":"2024 E.C.","questionText":"Arithmetic sequence a1 = 2, d = 3. Sum of first 20 terms?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"610"},{"id":"b","text":"590"},{"id":"c","text":"600"},{"id":"d","text":"620"}],"correctOptionId":"a","explanation":"S20 = 20/2 * (2*2 + 19*3) = 10 * (4 + 57) = 10 * 61 = 610.","difficulty":"Hard"}
"@

